33	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.IdentityKeys.of(owner))")
34	    @Mapping(target = "checkDigit", expression = "java(owner.getCustomerCode() == null ? null : org.springframework.samples.petclinic.util.Luhn.checkDigit(owner.getCustomerCode()))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
38	
39	    @Mapping(target = "id", ignore = true)
40	    @Mapping(target = "pets", ignore = true)
41	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
42	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
43	    Owner toOwner(OwnerFieldsDto ownerDto);
44	
45	    /** Store the telephone in E.164 form (see {@link E164#toE164}). */
46	    @Named("normalizeTelephone")
47	    default String normalizeTelephone(String telephone) {
48	        return E164.toE164(telephone);
49	    }
50	
51	    /** Store the address in normalized form (see {@link Addresses#normalize}). */
52	    @Named("normalizeAddress")
53	    default String normalizeAddress(String address) {
54	        return Addresses.normalize(address);
55	    }
56	
57	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
58	
59	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
60	
61	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
62	        OwnerPageDto ownerPageDto = new OwnerPageDto();
63	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
64	        ownerPageDto.setPage(ownerPage.getNumber());
65	        ownerPageDto.setSize(ownerPage.getSize());
66	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
67	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
68	        return ownerPageDto;
69	    }
70	}
