109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (DisposableDomains.isBlocked(owner)) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        Collection<Owner> owners = this.clinicService.findAllOwners();
118	        if (DailyRegistrations.countOn(owners, java.time.LocalDate.now()) >= 100) {
119	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
120	        }
121	        if (CityCodes.count(owners, owner) >= 50) {
